import {
  ProviderError,
  accountRouter,
  decodeJson,
  defineApp,
  defineProvider,
  object,
  router,
  secrets,
  string,
  withApprovals,
} from "apps";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";
import { vercelSignIn, signedInRouter } from "./mcp.js";

const User = object({ id: string(), username: string(), email: string() });

const vercel = defineProvider({
  name: "Vercel",
  hosts: ["api.vercel.com"],
  auth: {
    apiKey: secrets({
      label: "Access token",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
  },
  async health({ account, fetch, signal }) {
    const response = await fetch("https://api.vercel.com/v2/user", {
      signal,
      headers: { Authorization: `Bearer ${account.fields.token}` },
    });
    // Vercel answers an unknown or revoked token with 403 and `invalidToken: true`.
    if (response.status === 403 && (await response.clone().json()).error?.invalidToken === true)
      throw new ProviderError({ reason: "unauthorized", status: 403 });
    const { user } = await decodeJson(response, object({ user: User }));
    return {
      accountInfo: {
        externalId: user.id,
        username: user.username,
        email: user.email,
      },
    };
  },
});

export default defineApp(
  { user: { accounts: { vercel: vercel.many(), signIn: vercelSignIn.many() } }, icons },
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      await accountRouter(
        [
          ...(user?.accounts.vercel ?? []).map((account) => ({
            id: account.id,
            discover: () =>
              withApprovals(liveOpenapiRouter({ ...options, cache, fetch, signal, account }), (tool) =>
                tool.kind === "mutation" ? always() : undefined,
              ),
          })),
          ...(user?.accounts.signIn ?? []).map((account) => ({
            id: account.id,
            discover: () => signedInRouter(account, { cache, signal }),
          })),
        ],
        (account) => account.discover(),
        { signal },
      ),
      {
        title: "Vercel",
        description: "Projects, deployments, domains, environment variables, teams and the rest of the Vercel API.",
        instructions:
          "Most endpoints act on the token's personal scope unless you pass teamId (or slug). List teams first when the user names a team.",
        icons,
      },
    ),
  }),
);

import type { OpenapiToolNamesOptions } from "apps/openapi";

export const options = {
  source: { url: "https://openapi.vercel.sh/" },
  allowedOrigin: "https://api.vercel.com",
  securitySchemes: { bearerToken: { type: "http", scheme: "bearer" } },
  methods: { apiKey: [{ scheme: "bearerToken", field: "token", part: "value", prefix: "" }] },
  oauth: [],
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/vercel",
  "description": "Projects, deployments, domains, environment variables, teams and the rest of the Vercel API.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "Vercel"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.11",
    "@modelcontextprotocol/sdk": "1.32.1"
  }
}

import { defineProvider, oauth2, toolAnnotations, withApprovals, type AccountOf, type AppCache } from "apps";
import { mcpHealth, mcpRouter } from "apps/mcp";
import { always } from "apps/operations/approval";

const url = "https://mcp.vercel.com/";
const headers = (account: { fields: { access_token: string } }) => ({
  Authorization: `Bearer ${account.fields.access_token}`,
});

// A separate requirement keeps existing API-token accounts on their original provider identity.
export const vercelSignIn = defineProvider({
  name: "Vercel",
  hosts: ["mcp.vercel.com"],
  auth: { oauth: oauth2({ discover: url }) },
  health: (check) => mcpHealth(check, { url, headers: headers(check.account) }),
});

export const signedInRouter = async (
  account: AccountOf<typeof vercelSignIn>,
  context: { cache: AppCache; signal: AbortSignal },
) =>
  withApprovals(
    await mcpRouter({ url, account, headers: headers(account), ...context }),
    (tool) => (toolAnnotations(tool)?.destructiveHint === true ? always() : undefined),
  );
